SINA_SMART["anat3-pns"] = {"lecture":"anat3-pns","title":"Anatomy of the peripheral nervous system","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat3-pns:e0","text":"PNS: everything outside brain and cord; 12 cranial and 31 spinal nerve pairs.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e2","text":"Parasympathetic cranial nerves: III, VII, IX, X.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"anat3-pns:s1","text":"Describe and explain: Introduction","topic":"Introduction","sec":1,"importance":"standard","highYield":"untested"},{"id":"anat3-pns:e1","text":"Sensory cranial nerves I, II, VIII; motor III, IV, VI, XI, XII; mixed V, VII, IX, X.","topic":"The cranial nerves","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e3","text":"Olfactory axons cross the cribriform plate.","topic":"The cranial nerves","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e4","text":"Optic nerve lesion: ipsilateral blindness. Chiasm: bitemporal. Tract or cortex: contralateral homonymous hemianopia.","topic":"The cranial nerves","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e5","text":"Trigeminal ganglion in Meckel's cave; V1 superior orbital fissure, V2 foramen rotundum, V3 foramen ovale.","topic":"The cranial nerves","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e6","text":"Upper face bilateral input, lower face contralateral only.","topic":"The cranial nerves","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e7","text":"Facial canal: labyrinthine (narrowest), tympanic, mastoid; exits the stylomastoid foramen; five branches in the parotid.","topic":"The cranial nerves","sec":2,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e8","text":"Plexuses: cervical C1 to C5 (phrenic), brachial C4 to T1, lumbar (femoral), sacral L4 to S4 (sciatic).","topic":"The spinal nerves and plexuses","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e9","text":"Sciatic nerve: L4 to S3, below piriformis, divides near the popliteal fossa.","topic":"The spinal nerves and plexuses","sec":3,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e10","text":"Somatic motor: one neuron, acetylcholine on nicotinic receptors. Patellar reflex is monosynaptic.","topic":"The somatic nervous system","sec":4,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e11","text":"Sympathetic: T1 to L2, noradrenaline post. Parasympathetic: craniosacral, acetylcholine throughout.","topic":"The autonomic nervous system","sec":5,"importance":"core","highYield":"untested"},{"id":"anat3-pns:e12","text":"Horner's syndrome: ptosis, miosis, anhidrosis.","topic":"The autonomic nervous system","sec":5,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"n2z6q1":"a","zxxtaa":"a","4flp60":"a","hs4x8h":"a","hlv87n":"a","119zqs9":"a","t01tjz":"a","1sruiin":"a","d5xzf5":"a","1b1jmfr":"a","15k5ft8":"a","ht20ne":"a","ozyp9n":"a","nvdozq":"a","5l51er":"a","1g4mz2f":"a","66u9gx":"a","e5brli":"a","1xjeu7j":"a","asldq8":"a","mav1mg":"a","12db14f":"a","6s8xbq":"a","atssm9":"a","2wr8o4":"a","1jgr225":"x","aalqcv":"x"},"mapCounts":{"verified":0,"auto":25,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat3-pns:e0":{"s":0,"u":["PNS: everything outside brain and cord; 12 cranial and 31 spinal nerve pairs.","The peripheral nervous system is everything outside the brain and spinal cord: 12 pairs of cranial nerves and 31 pairs of spinal nerves , with their plexuses and ganglia.","Anatomically : cranial versus spinal."],"dp":[]},"anat3-pns:e2":{"s":0,"u":["Parasympathetic cranial nerves: III, VII, IX, X.","Anatomically : cranial versus spinal.","The peripheral nervous system is everything outside the brain and spinal cord: 12 pairs of cranial nerves and 31 pairs of spinal nerves , with their plexuses and ganglia."],"dp":[]},"anat3-pns:s1":{"s":1,"u":["The PNS is the communication link between the CNS and the body, carrying sensation to the CNS and motor commands to muscles and glands.","Anatomically it is the cranial nerves, spinal nerves and their branches, plexuses and ganglia ."],"dp":[]},"anat3-pns:e1":{"s":2,"u":["Sensory cranial nerves I, II, VIII; motor III, IV, VI, XI, XII; mixed V, VII, IX, X.","The largest cranial nerve, with a large sensory and small motor root from the pons; sensory fibres synapse in the Gasserian ganglion in Meckel's cave .","VIII Vestibulocochlear: Type = Sensory; Function = Hearing and balance."],"dp":[{"h":"Note","t":"Nerve types : sensory I, II, VIII; motor III, IV, VI, XI, XII; mixed V, VII, IX, X; parasympathetic III, VII, IX, X."}]},"anat3-pns:e3":{"s":2,"u":["Olfactory axons cross the cribriform plate.","Bipolar neurons of the olfactory epithelium send axons through the cribriform plate to the olfactory bulbs, then along the olfactory tracts to the olfactory cortex, amygdala and hypothalamus.","I Olfactory: Type = Sensory; Function = Smell."],"dp":[]},"anat3-pns:e4":{"s":2,"u":["Optic nerve lesion: ipsilateral blindness. Chiasm: bitemporal. Tract or cortex: contralateral homonymous hemianopia.","Optic tract: Contralateral homonymous hemianopia.","Optic chiasm: Bitemporal hemianopia."],"dp":[{"h":"Note","t":"Visual field lesions : optic nerve = ipsilateral blindness; chiasm = bitemporal hemianopia; optic tract or occipital cortex = contralateral homonymous hemianopia (macular sparing after a posterior cerebral artery stroke)."}]},"anat3-pns:e5":{"s":2,"u":["Trigeminal ganglion in Meckel's cave; V1 superior orbital fissure, V2 foramen rotundum, V3 foramen ovale.","Ophthalmic (sensory) via the superior orbital fissure; maxillary (sensory) via the foramen rotundum; mandibular (sensory and motor) via the foramen ovale.","The largest cranial nerve, with a large sensory and small motor root from the pons; sensory fibres synapse in the Gasserian ganglion in Meckel's cave ."],"dp":[{"h":"Memory aid","t":"'Standing Room Only' : V1 → Superior orbital fissure, V2 → foramen Rotundum, V3 → foramen Ovale. Trigeminal ganglion sits in Meckel's cave ."}]},"anat3-pns:e6":{"s":2,"u":["Upper face bilateral input, lower face contralateral only.","The upper face receives bilateral input, the lower face only contralateral ."],"dp":[{"h":"Why Bell's palsy closes nothing but a stroke closes the eye","t":"The facial nucleus part for the upper face receives fibres from both hemispheres, while the lower face part receives only the opposite side. A stroke cuts only one side's input, so the forehead is still driven by the other hemisphere and the patient can wrinkle it and close the eye. A lesion of the facial nerve itself cuts everything below it, so the whole half of the face falls. That one difference tells a stroke apart from Bell's palsy. Source: the lecture's facial nerve slides on bilateral and contralateral input."},{"h":"Clinical","t":"Facial nerve : UMN lesion spares the forehead (bilateral cortical input to the upper face); LMN lesion (Bell's palsy) paralyses the whole half-face. The labyrinthine segment is the narrowest part of the canal."}]},"anat3-pns:e7":{"s":2,"u":["Facial canal: labyrinthine (narrowest), tympanic, mastoid; exits the stylomastoid foramen; five branches in the parotid.","It exits by the stylomastoid foramen , enters the parotid and divides into five purely motor branches: temporal, zygomatic, buccal, marginal mandibular and cervical.","The nerve enters the internal auditory canal with CN VIII, then crosses the temporal bone in three segments: labyrinthine (narrowest, to the geniculate ganglion), tympanic (above the oval window) and mastoid (giving the nerve to stapedius and the chorda tympani)."],"dp":[]},"anat3-pns:e8":{"s":3,"u":["Plexuses: cervical C1 to C5 (phrenic), brachial C4 to T1, lumbar (femoral), sacral L4 to S4 (sciatic).","31 pairs : 8 cervical, 12 thoracic, 5 lumbar, 5 sacral and 1 coccygeal, each leaving through its intervertebral foramen.","Lumbar: Roots = Lumbar; Main nerves = Pelvis and anterior leg; the femoral nerve and its saphenous branch."],"dp":[{"h":"Why a herniated disc causes pain down the leg","t":"The sciatic nerve is built from the L4 to S3 roots. A disc bulging at the lower lumbar levels presses on one of those roots before it even joins the nerve, and the brain reads the pain as coming from wherever that root supplies, down the back of the thigh and into the leg. That is why the pain of sciatica follows a dermatome rather than staying in the back. Source: the lecture's sciatic nerve and sciatica slides."},{"h":"Note","t":"Plexuses : cervical (phrenic nerve, C3-C5 keeps the diaphragm alive), brachial (radial, axillary, ulnar, median), lumbar (femoral), sacral ( sciatic L4-S3 , below piriformis, splits into tibial and common fibular)."},{"h":"Note","t":"The lecture lists cervical C1-C5 and brachial C4-T1. Most textbooks give cervical C1-C4 and brachial C5-T1 (C4 joins only in a 'prefixed' plexus). Know your professor's version and the textbook one."}]},"anat3-pns:e9":{"s":3,"u":["Sciatic nerve: L4 to S3, below piriformis, divides near the popliteal fossa.","Near the popliteal fossa it divides into the tibial and common fibular nerves.","The sciatic nerve is the largest and longest in the body, from L4 to S3."],"dp":[]},"anat3-pns:e10":{"s":4,"u":["Somatic motor: one neuron, acetylcholine on nicotinic receptors. Patellar reflex is monosynaptic.","The patellar reflex is monosynaptic and tests spinal segment integrity.","Motor division: a single neuron from the ventral horn or a cranial motor nucleus straight to the muscle, with no ganglion, releasing acetylcholine onto nicotinic receptors."],"dp":[{"h":"Clinical","t":"Patellar reflex is monosynaptic ( L3-L4 ): it tests one segment's sensory and motor integrity."}]},"anat3-pns:e11":{"s":5,"u":["Sympathetic: T1 to L2, noradrenaline post. Parasympathetic: craniosacral, acetylcholine throughout.","Post: noradrenaline or adrenaline; Parasympathetic = Both acetylcholine.","Transmitters: acetylcholine for all preganglionic fibres and parasympathetic postganglionic fibres; noradrenaline for most sympathetic postganglionic fibres, except sweat glands (acetylcholine)."],"dp":[{"h":"Note","t":"Somatic motor = 1 neuron (ACh on nicotinic receptors). Autonomic = 2 neurons : sympathetic thoracolumbar T1-L2 (short pre, long post, noradrenaline); parasympathetic craniosacral (long pre, short post, ACh)."},{"h":"Note","t":"Sweat glands are sympathetic but use acetylcholine postganglionically; the adrenal medulla receives preganglionic fibres directly."}]},"anat3-pns:e12":{"s":5,"u":["Horner's syndrome: ptosis, miosis, anhidrosis.","Clinical: diabetic autonomic neuropathy (orthostatic hypotension, bladder dysfunction, impotence); Horner's syndrome (ptosis, miosis, anhidrosis); vasovagal syncope; Raynaud's disease."],"dp":[{"h":"Why sympathetic fibres reach the head from the chest","t":"Sympathetic outflow only leaves the cord between T1 and L2, yet the eye, face and sweat glands of the head are supplied too. The fibres climb up the sympathetic chain to the superior cervical ganglion, then ride on the carotid arteries into the head. A lesion anywhere along that long route, including a lung apex tumour, can cause Horner's syndrome. Source: the lecture's sympathetic anatomy and Horner's syndrome slides."},{"h":"Clinical","t":"Horner syndrome (sympathetic chain lesion): ptosis, miosis, anhidrosis on the same side (e.g. apical lung tumour)."}]}},"meta":{"n2z6q1":{"a":"recall","vg":"anat3-pns:e2/recall/1"},"zxxtaa":{"a":"recall","vg":"anat3-pns:s1/recall/1"},"4flp60":{"a":"recall","vg":"anat3-pns:e2/recall/2"},"hs4x8h":{"a":"recall","vg":"anat3-pns:e2/recall/3"},"hlv87n":{"a":"recall","vg":"anat3-pns:e3/recall/1"},"119zqs9":{"a":"recall","vg":"anat3-pns:e4/recall/1"},"t01tjz":{"a":"application","vg":"anat3-pns:e4/application/1"},"1sruiin":{"a":"recall","vg":"anat3-pns:s1/recall/2"},"d5xzf5":{"a":"recall","vg":"anat3-pns:e5/recall/1"},"1b1jmfr":{"a":"recall","vg":"anat3-pns:e5/recall/2"},"15k5ft8":{"a":"relationship","vg":"anat3-pns:e6/relationship/1"},"ht20ne":{"a":"recall","vg":"anat3-pns:e7/recall/1"},"ozyp9n":{"a":"recall","vg":"anat3-pns:e7/recall/2"},"nvdozq":{"a":"recall","vg":"anat3-pns:e8/recall/1"},"5l51er":{"a":"recall","vg":"anat3-pns:e8/recall/1"},"1g4mz2f":{"a":"recall","vg":"anat3-pns:e8/recall/2"},"66u9gx":{"a":"recall","vg":"anat3-pns:e9/recall/1"},"e5brli":{"a":"recall","vg":"anat3-pns:e9/recall/2"},"1xjeu7j":{"a":"recall","vg":"anat3-pns:e10/recall/1"},"asldq8":{"a":"recall","vg":"anat3-pns:e10/recall/2"},"mav1mg":{"a":"recall","vg":"anat3-pns:e11/recall/1"},"12db14f":{"a":"recall","vg":"anat3-pns:e11/recall/2"},"6s8xbq":{"a":"recall","vg":"anat3-pns:e2/recall/3"},"atssm9":{"a":"recall","vg":"anat3-pns:e12/recall/1"},"2wr8o4":{"a":"recall","vg":"anat3-pns:e2/recall/4"}},"explRev":"b77972adc77e"};
